```python
# ============================================
# File: components/DocEditor.tsx
# High-level document editor integrated with Firebase (Firestore + Storage)
# - Loads/saves a doc by slug
# - Title, tags, markdown content
# - Auto-save and manual save
# - Image upload to Storage
# - Rename slug & Delete document
# ============================================
doc_editor_tsx = r'''
"use client";

import * as React from "react";
import { db, storage } from "@/lib/firebase";
import {
  doc,
  getDoc,
  onSnapshot,
  serverTimestamp,
  setDoc,
  updateDoc,
  deleteDoc,
} from "firebase/firestore";
import { ref, uploadBytes, getDownloadURL } from "firebase/storage";
import { MarkdownRXEditor, MarkdownRXPreview } from "@/components/MarkdownRX";
import { useRouter } from "next/navigation";

type DocData = {
  title: string;
  content: string;
  tags?: string[];
  createdAt?: any;
  updatedAt?: any;
};

function slugify(input: string) {
  return input
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)+/g, "");
}

export default function DocEditor({ slug }: { slug: string }) {
  const [docData, setDocData] = React.useState<DocData | null>(null);
  const [title, setTitle] = React.useState<string>("");
  const [tagsText, setTagsText] = React.useState<string>("");
  const [content, setContent] = React.useState<string>("");
  const [saving, setSaving] = React.useState<boolean>(false);
  const [renaming, setRenaming] = React.useState<boolean>(false);
  const [deleting, setDeleting] = React.useState<boolean>(false);
  const [lastSavedAt, setLastSavedAt] = React.useState<Date | null>(null);

  const router = useRouter();

  // Subscribe to Firestore doc by slug
  React.useEffect(() => {
    const refDoc = doc(db, "docs", slug);
    const unsub = onSnapshot(refDoc, (snap) => {
      if (!snap.exists()) {
        setDocData(null);
        setTitle("");
        setTagsText("");
        setContent("");
        return;
      }
      const data = snap.data() as DocData;
      setDocData(data);
      setTitle(data.title || "");
      setTagsText((data.tags || []).join(", "));
      setContent(data.content || "");
    });
    return () => unsub();
  }, [slug]);

  async function save() {
    setSaving(true);
    const refDoc = doc(db, "docs", slug);
    const payload: DocData = {
      title: title.trim() || "Untitled",
      content,
      tags: tagsText
        .split(",")
        .map((t) => t.trim())
        .filter(Boolean),
      updatedAt: serverTimestamp(),
      createdAt: (await getDoc(refDoc)).exists() ? docData?.createdAt ?? serverTimestamp() : serverTimestamp(),
    } as DocData;
    await setDoc(refDoc, payload, { merge: true });
    setSaving(false);
    setLastSavedAt(new Date());
  }

  // Auto-save 1.5s after content or title changes
  React.useEffect(() => {
    const id = setTimeout(() => {
      if (title || content) save();
    }, 1500);
    return () => clearTimeout(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [title, content, tagsText]);

  async function onUploadImage(file: File) {
    const path = `docs/${slug}/images/${Date.now()}-${file.name}`;
    const storageRef = ref(storage, path);
    await uploadBytes(storageRef, file);
    return getDownloadURL(storageRef);
  }

  async function onRename() {
    const next = prompt("New slug:", slug);
    if (!next) return;
    const newSlug = slugify(next);
    if (newSlug === slug) return;

    const oldRef = doc(db, "docs", slug);
    const snap = await getDoc(oldRef);
    if (!snap.exists()) return;

    const data = snap.data();
    const newRef = doc(db, "docs", newSlug);
    setRenaming(true);
    await setDoc(newRef, { ...data, updatedAt: serverTimestamp() });
    await deleteDoc(oldRef);
    setRenaming(false);
    router.replace(`/docs/${newSlug}`);
  }

  async function onDelete() {
    if (!confirm("Delete this document? This cannot be undone.")) return;
    setDeleting(true);
    await deleteDoc(doc(db, "docs", slug));
    setDeleting(false);
    router.replace("/docs");
  }

  return (
    <div className="space-y-4">
      <div className="flex flex-col gap-2 md:flex-row md:items-center">
        <input
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          className="w-full rounded border px-3 py-2"
          placeholder="Document title"
        />
        <div className="flex items-center gap-2 md:ml-auto">
          <button onClick={save} className="rounded border px-3 py-2">
            {saving ? "Saving..." : "Save"}
          </button>
          <button onClick={onRename} className="rounded border px-3 py-2" disabled={renaming}>
            {renaming ? "Renaming..." : "Rename"}
          </button>
          <button onClick={onDelete} className="rounded border px-3 py-2 text-red-600" disabled={deleting}>
            {deleting ? "Deleting..." : "Delete"}
          </button>
        </div>
      </div>

      <input
        value={tagsText}
        onChange={(e) => setTagsText(e.target.value)}
        className="w-full rounded border px-3 py-2"
        placeholder="tags (comma separated)"
      />

      <MarkdownRXEditor value={content} onChange={setContent} onUploadImage={onUploadImage} />

      <div className="text-sm text-muted-foreground">
        {lastSavedAt ? `Last saved ${lastSavedAt.toLocaleTimeString()}` : ""}
      </div>

      <div className="rounded border p-4">
        <h2 className="mb-2 text-lg font-semibold">Live Preview</h2>
        <MarkdownRXPreview value={content} />
      </div>
    </div>
  );
}
'''
```

