# File: app/docs/page.client.tsx
# Client component for listing and creating docs
# ============================================
docs_index_client_tsx = r'''
"use client";

import * as React from "react";
import Link from "next/link";
import { db } from "@/lib/firebase";
import {
  collection,
  onSnapshot,
  orderBy,
  query,
  setDoc,
  doc,
  serverTimestamp,
} from "firebase/firestore";

function slugify(input: string) {
  return input
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)+/g, "");
}

export default function DocsIndexClient() {
  const [docs, setDocs] = React.useState<any[]>([]);
  const [qText, setQText] = React.useState("");
  const [newTitle, setNewTitle] = React.useState("");
  const [creating, setCreating] = React.useState(false);

  React.useEffect(() => {
    const qy = query(collection(db, "docs"), orderBy("updatedAt", "desc"));
    const unsub = onSnapshot(qy, (snap) => {
      const rows = snap.docs.map((d) => ({ id: d.id, ...(d.data() as any) }));
      setDocs(rows);
    });
    return () => unsub();
  }, []);

  async function createDoc() {
    if (!newTitle.trim()) return;
    setCreating(true);
    const slug = slugify(newTitle);
    const refDoc = doc(db, "docs", slug);
    await setDoc(refDoc, {
      title: newTitle.trim(),
      content: "# New document\n\nStart writing…",
      tags: [],
      createdAt: serverTimestamp(),
      updatedAt: serverTimestamp(),
    }, { merge: false });
    setNewTitle("");
    setCreating(false);
  }

  const filtered = qText
    ? docs.filter((d) =>
        (d.title || "").toLowerCase().includes(qText.toLowerCase()) ||
        (d.tags || []).join(",").toLowerCase().includes(qText.toLowerCase())
      )
    : docs;

  return (
    <div className="p-4 space-y-6">
      <div className="flex flex-col gap-2 md:flex-row md:items-center">
        <input
          className="w-full rounded border px-3 py-2"
          placeholder="Search by title or tag"
          value={qText}
          onChange={(e) => setQText(e.target.value)}
        />
        <div className="md:ml-auto flex gap-2">
          <input
            className="rounded border px-3 py-2"
            placeholder="New doc title"
            value={newTitle}
            onChange={(e) => setNewTitle(e.target.value)}
          />
          <button onClick={createDoc} disabled={creating} className="rounded border px-3 py-2">
            {creating ? "Creating…" : "Create"}
          </button>
        </div>
      </div>

      <ul className="divide-y rounded border bg-card">
        {filtered.map((d) => (
          <li key={d.id} className="p-3 hover:bg-muted/40">
            <Link href={`/docs/${d.id}`} className="font-medium">
              {d.title || d.id}
            </Link>
            <div className="text-xs text-muted-foreground">
              {(d.tags || []).map((t: string) => (
                <span key={t} className="mr-2 inline-block rounded bg-muted px-1.5 py-0.5">{t}</span>
              ))}
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
}
'''
