    def _parse_points_json(self, text: str) -> Optional[Dict[int, int]]:
        text = (text or "").strip()
        if not text:
            return None
        try:
            obj = json.loads(text)
            if not isinstance(obj, dict):
                raise ValueError("Points must be a JSON object, e.g. {\"1\":25,\"2\":18}")
            # Convert keys to int
            points = {int(k): int(v) for k, v in obj.items()}
            self.data._validate_points_map(points)
            return points
        except Exception as e:
            raise ValueError(f"Invalid per-event points: {e}")

    def _add_event(self):
