    def _fill_event_combo(self, combo: ttk.Combobox, items: List[Tuple[int, str]]):
        # store mapping in widget for reverse lookup
        ids = [i for i, _ in items]
        labels = [f"{i} - {n}" for i, n in items]
        combo['values'] = labels
        # keep IntVar but display label: intercept selection with custom handler
        # Here we set mapping via a dict on the widget
        mapping = {f"{i} - {n}": i for i, n in items}
        combo._id_mapping = mapping  # type: ignore[attr-defined]
        def on_select(_e=None, var=combo.cget('textvariable')):
            # Update linked IntVar with mapped ID
            sel = combo.get()
            pid = mapping.get(sel, 0)
            # Write to underlying IntVar
            vname = var
            if isinstance(vname, str) and vname:
                # resolve to tk variable
                try:
                    self.nametowidget(vname)
                except Exception:
                    pass
            combo.configure()
            if isinstance(combo.cget('textvariable'), str):
                # when bound to IntVar, set via associated variable object if possible
                try:
                    # Find bound variable object
                    # Fallback: parse int from label prefix before ' - '
                    idx = sel.split(' - ')[0]
                    combo._variable.set(int(idx))  # type: ignore[attr-defined]
                except Exception:
                    pass
        # attach variable reference for setting
        try:
            combo._variable = combo.cget('textvariable') and self.globalgetvar(name=combo.cget('textvariable'))  # type: ignore[attr-defined]
        except Exception:
            combo._variable = None  # type: ignore[attr-defined]
        combo.bind('<<ComboboxSelected>>', on_select)
        # If current int var value exists, set display text
        try:
            current_id = int(self.globalgetvar(name=combo.cget('textvariable')))
            for lbl, iid in mapping.items():
                if iid == current_id:
                    combo.set(lbl)
                    break
        except Exception:
            pass

