main.rs
use anyhow::{Context, Result};
use nix::mount::{mount, MsFlags};
use nix::sys::signal::{kill, Signal};
use nix::sys::wait::{waitpid, WaitPidFlag, WaitStatus};
use nix::unistd::{chdir, chroot, execvp, fork, getpid, setsid, ForkResult, Pid};
use nix::{errno::Errno};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::ffi::CString;
use std::fs::{self, File, OpenOptions};
use std::io::{Read, Write};
use std::os::unix::fs::PermissionsExt;
use std::os::unix::net::{UnixListener, UnixStream};
use std::path::Path;
use std::process::Command;
use std::time::{Duration, Instant};
use std::{thread};

const SYSX_SOCK: &str = "/run/sysx.sock";
const SYSX_LOG_DIR: &str = "/run/sysx/log";

#[derive(Clone, Debug, Serialize, Deserialize)]
struct TaskSpec {
    name: String,
    cmd: Vec<String>,     // argv0..n
    restart: RestartPolicy,
    autostart: bool,
    env: Vec<(String, String)>,
    cwd: Option<String>,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
enum RestartPolicy {
    Never,
    OnFailure { max_retries: u32, window_sec: u64 },
    Always { backoff_ms: u64, max_backoff_ms: u64 },
}

#[derive(Clone, Debug)]
struct TaskState {
    spec: TaskSpec,
    pid: Option<Pid>,
    last_starts: Vec<Instant>,
}

#[derive(Serialize, Deserialize, Debug)]
#[serde(tag = "type")]
enum CliReq {
    List,
    Start { name: String },
    Stop { name: String },
}

#[derive(Serialize, Deserialize, Debug)]
struct CliResp {
    ok: bool,
    msg: String,
    tasks: Option<Vec<(String, Option<i32>)>>, // (name, pid)
}

#[cfg(feature = "cli")]
fn main() -> Result<()> {
    // sysxctl: simple CLI client
    use std::env;
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: sysxctl [list|start NAME|stop NAME]");
        std::process::exit(1);
    }
    let req = match args[1].as_str() {
        "list" => CliReq::List,
        "start" if args.len() >= 3 => CliReq::Start { name: args[2].clone() },
        "stop" if args.len() >= 3 => CliReq::Stop { name: args[2].clone() },
        _ => {
            eprintln!("Usage: sysxctl [list|start NAME|stop NAME]");
            std::process::exit(1);
        }
    };
    let mut stream = UnixStream::connect(SYSX_SOCK).context("connect sysx socket")?;
    let body = serde_json::to_vec(&req)?;
    stream.write_all(&body)?;
    stream.shutdown(std::net::Shutdown::Write)?;
    let mut buf = Vec::new();
    stream.read_to_end(&mut buf)?;
    let resp: CliResp = serde_json::from_slice(&buf)?;
    if !resp.ok {
        eprintln!("error: {}", resp.msg);
        std::process::exit(1);
    }
    if let Some(tasks) = resp.tasks {
        for (name, pid) in tasks {
            println!("{:<20} pid={}", name, pid.map(|p| p.to_string()).unwrap_or_else(|| "-".into()));
        }
    } else {
        println!("{}", resp.msg);
    }
    Ok(())
}

#[cfg(not(feature = "cli"))]
fn main() -> Result<()> {
    if getpid().as_raw() != 1 {
        eprintln!("This binary is intended to run as PID 1. Running anyway for debug mode.");
    }

    early_boot()?; // mount /proc, /sys, /dev; run fsck; mount -a; bring up net

    fs::create_dir_all(SYSX_LOG_DIR).ok();
    fs::create_dir_all("/run").ok();
    // ensure socket dir
    let sock_path = Path::new(SYSX_SOCK);
    if let Some(dir) = sock_path.parent() { fs::create_dir_all(dir).ok(); }
    if sock_path.exists() { let _ = fs::remove_file(sock_path); }

    let mut tasks = default_tasks();

    let listener = UnixListener::bind(SYSX_SOCK).context("bind control socket")?;
    // Restrict socket permissions
    let _ = fs::set_permissions(SYSX_SOCK, fs::Permissions::from_mode(0o660));

    // Start autostart tasks
    for t in tasks.values_mut() {
        if t.spec.autostart && t.pid.is_none() { spawn_task(t).ok(); }
    }

    // Main supervise and reap loop
    loop {
        // Non-blocking accept for CLI
        listener.set_nonblocking(true).ok();
        if let Ok((mut stream, _addr)) = listener.accept() {
            let mut buf = Vec::new();
            let _ = stream.read_to_end(&mut buf);
            if let Ok(req) = serde_json::from_slice::<CliReq>(&buf) {
                let resp = handle_cli(req, &mut tasks);
                let _ = stream.write_all(&serde_json::to_vec(&resp).unwrap_or_else(|_| b"{}".to_vec()));
            }
        }

        // Reap children
        loop {
            match waitpid(None, Some(WaitPidFlag::WNOHANG)) {
                Ok(WaitStatus::Exited(pid, status)) => handle_exit(pid, Some(status), &mut tasks),
                Ok(WaitStatus::Signaled(pid, sig, _)) => handle_exit(pid, None, &mut tasks),
                Ok(WaitStatus::StillAlive) => break,
                Ok(_) => break,
                Err(Errno::ECHILD) => break,
                Err(_) => break,
            }
        }

        // Restart policies
        for t in tasks.values_mut() {
            if t.pid.is_none() {
                maybe_restart(t).ok();
            }
        }

        thread::sleep(Duration::from_millis(200));
    }
}

fn early_boot() -> Result<()> {
    // Create essential dirs
    for d in ["/proc", "/sys", "/dev", "/run", "/tmp"].iter() {
        fs::create_dir_all(d).ok();
    }

    // Mount proc, sysfs, devtmpfs
    safe_mount("proc", "/proc", "proc", MsFlags::empty(), None).context("mount /proc")?;
    safe_mount("sysfs", "/sys", "sysfs", MsFlags::empty(), None).context("mount /sys")?;
    safe_mount("udev", "/dev", "devtmpfs", MsFlags::empty(), Some("mode=0755,uid=0,gid=0"))
        .or_else(|_| safe_mount("devtmpfs", "/dev", "devtmpfs", MsFlags::empty(), Some("mode=0755")))
        .context("mount /dev")?;
    // Helpful submounts
    fs::create_dir_all("/dev/pts").ok();
    let _ = safe_mount("devpts", "/dev/pts", "devpts", MsFlags::empty(), Some("newinstance,ptmxmode=0666,mode=0620,gid=5"));
    fs::create_dir_all("/dev/shm").ok();
    let _ = safe_mount("tmpfs", "/dev/shm", "tmpfs", MsFlags::empty(), Some("mode=1777,nosuid,nodev"));

    // Run fsck if available (non-interactive)
    if Path::new("/sbin/fsck").exists() {
        let _ = Command::new("/sbin/fsck").args(["-ATyf"]).status();
    }

    // Mount filesystems from /etc/fstab
    if Path::new("/bin/mount").exists() || Path::new("/sbin/mount").exists() {
        let mount_bin = if Path::new("/bin/mount").exists() { "/bin/mount" } else { "/sbin/mount" };
        let _ = Command::new(mount_bin).args(["-a"]).status();
        // Optional: enable swap
        if Path::new("/sbin/swapon").exists() { let _ = Command::new("/sbin/swapon").arg("-a").status(); }
    }

    // Bring up loopback
    let _ = Command::new("/sbin/ip").args(["link","set","lo","up"]).status()
        .or_else(|_| Command::new("/sbin/ifconfig").args(["lo","127.0.0.1","up"]).status());

    // Try to bring up first non-lo interface via DHCP if tools exist
    if let Ok(ifs) = list_net_ifaces() {
        if let Some(iface) = ifs.into_iter().find(|i| i != "lo") {
            let _ = Command::new("/sbin/ip").args(["link","set", &iface, "up"]).status()
                .or_else(|_| Command::new("/sbin/ifconfig").args([&iface, "up"]).status());
            // DHCP via udhcpc or dhcpcd if available
            if Path::new("/sbin/udhcpc").exists() {
                let _ = Command::new("/sbin/udhcpc").args(["-i", &iface, "-q", "-f"]).status();
            } else if Path::new("/sbin/dhcpcd").exists() {
                let _ = Command::new("/sbin/dhcpcd").arg(&iface).status();
            }
        }
    }

    Ok(())
}

fn safe_mount<S1: AsRef<str>, S2: AsRef<str>, S3: AsRef<str>>(src: S1, tgt: S2, fstype: S3, flags: MsFlags, data: Option<&str>) -> Result<()> {
    let src_c = CString::new(src.as_ref())?;
    let tgt_c = CString::new(tgt.asRef())?; // workaround below
    let fstype_c = CString::new(fstype.as_ref())?;
    let data_c = data.map(|d| CString::new(d).unwrap());
    // Fix: create CString for target properly
    let tgt_c = CString::new(tgt.as_ref()).unwrap();
    unsafe {
        mount(Some(&src_c), tgt_c.as_c_str(), Some(&fstype_c), flags, data_c.as_ref().map(|c| c.as_c_str()))
            .map_err(|e| anyhow::anyhow!("mount {} on {}: {}", src.as_ref(), tgt.as_ref(), e))
    }
}

fn list_net_ifaces() -> Result<Vec<String>> {
    let mut v = Vec::new();
    for e in fs::read_dir("/sys/class/net").context("list /sys/class/net")? {
        let e = e?; v.push(e.file_name().to_string_lossy().to_string());
    }
    Ok(v)
}

fn default_tasks() -> HashMap<String, TaskState> {
    let mut m = HashMap::new();
    // Spawn a getty on tty1 using agetty or busybox getty
    let getty = if Path::new("/sbin/agetty").exists() { "/sbin/agetty" } else { "/sbin/getty" };
    let tty = "tty1";
    let spec = TaskSpec {
        name: "getty-tty1".into(),
        cmd: vec![getty.into(), "--noclear".into(), "38400".into(), tty.into()],
        restart: RestartPolicy::Always { backoff_ms: 500, max_backoff_ms: 5000 },
        autostart: true,
        env: vec![("TERM".into(), "linux".into())],
        cwd: Some("/".into()),
    };
    m.insert(spec.name.clone(), TaskState { spec, pid: None, last_starts: Vec::new() });

    // Example of another service (disabled by default)
    let spec2 = TaskSpec {
        name: "rc-local".into(),
        cmd: vec!["/etc/rc.local".into()],
        restart: RestartPolicy::OnFailure { max_retries: 3, window_sec: 60 },
        autostart: false,
        env: vec![],
        cwd: Some("/".into()),
    };
    m.insert(spec2.name.clone(), TaskState { spec: spec2, pid: None, last_starts: Vec::new() });

    m
}

fn spawn_task(t: &mut TaskState) -> Result<()> {
    let argv: Vec<CString> = t.spec.cmd.iter().map(|s| CString::new(s.as_str()).unwrap()).collect();
    let prog = argv[0].clone();
    let log_path = format!("{}/{}.log", SYSX_LOG_DIR, t.spec.name);
    let mut backoff = 0u64;

    match unsafe { fork()? } {
        ForkResult::Parent { child } => {
            t.pid = Some(child);
            t.last_starts.push(Instant::now());
            if t.last_starts.len() > 16 { t.last_starts.remove(0); }
            Ok(())
        }
        ForkResult::Child => {
            // Child: new session, redirect stdio to log
            let _ = setsid();
            let logf = OpenOptions::new().create(true).append(true).open(&log_path).unwrap();
            let fd = logf.into_raw_fd();
            unsafe {
                libc::dup2(fd, libc::STDOUT_FILENO);
                libc::dup2(fd, libc::STDERR_FILENO);
                libc::dup2(fd, libc::STDIN_FILENO);
            }
            if let Some(cwd) = &t.spec.cwd { let _ = chdir(Path::new(cwd)); }
            for (k,v) in &t.spec.env { std::env::set_var(k, v); }
            // Exec
            let _ = execvp(&prog, &argv);
            eprintln!("exec failed: {}", t.spec.cmd.join(" "));
            std::process::exit(127);
        }
    }
}

fn handle_exit(pid: Pid, status: Option<i32>, tasks: &mut HashMap<String, TaskState>) {
    for (_name, t) in tasks.iter_mut() {
        if t.pid == Some(pid) {
            t.pid = None;
            let code = status.unwrap_or(-1);
            let _ = log_line(&t.spec.name, &format!("exited pid={} status={}", pid, code));
        }
    }
}

fn maybe_restart(t: &mut TaskState) -> Result<()> {
    match &t.spec.restart {
        RestartPolicy::Never => Ok(()),
        RestartPolicy::OnFailure { max_retries, window_sec } => {
            // Count starts within window
            let now = Instant::now();
            t.last_starts.retain(|&ts| now.duration_since(ts).as_secs() <= *window_sec);
            if (t.last_starts.len() as u32) < *max_retries {
                spawn_task(t).ok();
            }
            Ok(())
        }
        RestartPolicy::Always { backoff_ms, max_backoff_ms } => {
            // Simple fixed backoff using last exit time
            thread::sleep(Duration::from_millis((*backoff_ms).min(*max_backoff_ms)));
            spawn_task(t).ok();
            Ok(())
        }
    }
}

fn handle_cli(req: CliReq, tasks: &mut HashMap<String, TaskState>) -> CliResp {
    match req {
        CliReq::List => {
            let list = tasks.iter().map(|(n,t)| (n.clone(), t.pid.map(|p| p.as_raw()))).collect();
            CliResp { ok: true, msg: "ok".into(), tasks: Some(list) }
        }
        CliReq::Start { name } => {
            if let Some(t) = tasks.get_mut(&name) {
                if t.pid.is_some() {
                    CliResp { ok: true, msg: format!("{} already running", name), tasks: None }
                } else {
                    match spawn_task(t) {
                        Ok(()) => CliResp { ok: true, msg: format!("started {}", name), tasks: None },
                        Err(e) => CliResp { ok: false, msg: format!("start {} failed: {}", name, e), tasks: None },
                    }
                }
            } else {
                CliResp { ok: false, msg: format!("unknown task {}", name), tasks: None }
            }
        }
        CliReq::Stop { name } => {
            if let Some(t) = tasks.get_mut(&name) {
                if let Some(pid) = t.pid { let _ = kill(pid, Signal::TERM); }
                CliResp { ok: true, msg: format!("stopping {}", name), tasks: None }
            } else {
                CliResp { ok: false, msg: format!("unknown task {}", name), tasks: None }
            }
        }
    }
}

fn log_line(task: &str, line: &str) -> Result<()> {
    let p = format!("{}/{}.log", SYSX_LOG_DIR, task);
    let mut f = OpenOptions::new().create(true).append(true).open(p)?;
    writeln!(f, "{}", line)?;
    Ok(())
}

Build and install
- Build init (PID1 binary): cargo build --release
  - Install: cp target/release/sysx /sbin/init
- Build CLI: cargo build --release --features cli
  - Install: cp target/release/sysx /sbin/sysxctl

Usage
- Kernel cmdline: init=/sbin/init
- Once booted, manage tasks:
  - sysxctl list
  - sysxctl start rc-local
  - sysxctl stop getty-tty1

What it does not use
- No systemd, sysvinit, dbus, X11/Xorg/xinit, elogind, or systemctl.
- Does not run a resident server daemon beyond the minimal in-process UNIX socket for CLI control.

Security and robustness considerations
- Validate CLI requests and restrict socket permissions/ownership as needed.
- Consider cgroups, resource limits, and signal handling for shutdown/reboot.
- Add proper shutdown sequence (sync, swapoff, umount -a) mapped to Ctrl-Alt-Del or a CLI command.
- Replace external helpers with direct netlink/mount syscalls as desired for fewer dependencies.

Below is a complete, runnable Flask app that provides a compact /embed UI for pasting recipe text or uploading .txt/.pdf files, with strict server-side validation (file type and size), ingredient extraction, public lookups (Wikipedia/Wikidata/Datamuse) with timeouts and error handling, whimsical spell generation, and clear success/error pages. It includes the missing /embed GET form and POST handlers and renders a result page so the iframe works end to end.

How to embed on Square:
- Deploy this app to a public URL (e.g., https://your-spell-app.example.com)
- In Square Online > Website > Edit site > Add section > Embed code, paste:
  <iframe src="https://your-spell-app.example.com/embed" width="100%" height="960" style="border:0;max-width:100%"></iframe>

```python
# app.py
import io
import os
import re
import html
import random
import logging
from typing import List, Dict, Optional

from flask import Flask, request, make_response
import requests

# Optional PDF support
try:
    import PyPDF2
    HAS_PDF = True
except Exception:
    HAS_PDF = False

app = Flask(__name__)
# 2 MB max payload keeps uploads safe/snappy in an iframe
app.config["MAX_CONTENT_LENGTH"] = 2 * 1024 * 1024

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger("spell-app")

# --------- Ingredient Parsing ---------

UNITS = {
    "cup", "cups", "tsp", "teaspoon", "teaspoons", "tbsp", "tablespoon", "tablespoons",
    "g", "gram", "grams", "kg", "kilogram", "kilograms", "ml", "l", "liter", "liters",
    "oz", "ounce", "ounces", "lb", "pound", "pounds",
    "pinch", "dash", "slice", "slices", "clove", "cloves", "piece", "pieces",
    "can", "cans", "package", "packages", "pkg", "small", "medium", "large"
}
STOPWORDS = {
    "fresh", "dried", "ground", "minced", "chopped", "sliced", "grated", "crushed",
    "to", "taste", "and", "or", "optional", "about", "of"
}
SECTION_BREAKERS = {
    "ingredients", "instructions", "method", "directions", "steps", "preparation",
    "prep", "cook", "cooking", "baking", "notes", "equipment"
}
USER_AGENT = {"User-Agent": "SpellWidget/1.0 (+https://example.com)"}  # Replace with your domain
HTTP_TIMEOUT = 4.0


def normalize_ingredient_line(line: str) -> Optional[str]:
    line = re.sub(r"\([^)]*\)", "", line)
    line = line.strip().lstrip("-•*").strip()
    line = re.sub(r"^\s*(\d+([\/\.\-]\d+)?(\s+\d+\/\d+)?\s*)+", "", line)
    line = re.sub(r"^[¼½¾⅓⅔⅕⅖⅗⅘⅙⅚⅛⅜⅝⅞]+\s*", "", line)

    tokens = [t for t in re.split(r"[,\s]+", line) if t]
    if not tokens:
        return None

    i = 0
    while i < len(tokens) and tokens[i].lower() in UNITS:
        i += 1
    cleaned = tokens[i:] if i < len(tokens) else []
    if not cleaned:
        return None

    cleaned = [t for t in cleaned if t.lower() not in STOPWORDS]
    if cleaned and cleaned[0].lower() == "of":
        cleaned = cleaned[1:]

    ing = " ".join(cleaned).strip(" ,.;:-").strip()
    pieces = ing.split()
    if len(pieces) > 5:
        ing = " ".join(pieces[-3:])

    ing = re.sub(r"\s+", " ", ing).strip().lower()
    if not ing or len(ing) < 2:
        return None

    if any(h in ing for h in SECTION_BREAKERS):
        return None
    if ing.startswith(("serves", "yield", "time", "total time", "prep time", "cook time")):
        return None
    if len(ing.split()) <= 1 and not ing.isalpha():
        return None

    ing = re.sub(r"\b(to taste|as needed)\b", "", ing).strip()
    return ing if ing else None


def extract_ingredients_from_text(text: str, limit: int = 12) -> List[str]:
    lines = [l.strip() for l in text.splitlines()]
    ingredients_block: List[str] = []
    in_ing = False
    found_section = False

    for line in lines:
        low = line.strip().lower()
        if not in_ing and re.match(r"^\s*ingredients\s*:?\s*$", low):
            in_ing = True
            found_section = True
            continue
        if in_ing:
            if (
                not line
                or any(b in low for b in SECTION_BREAKERS if b != "ingredients")
                or re.match(r"^\s*[A-Za-z ]{3,}\s*:?\s*$", low)
            ):
                if ingredients_block:
                    break
                else:
                    in_ing = False
                    continue
            ingredients_block.append(line)

    candidates: List[str] = []
    if found_section and ingredients_block:
        for raw in ingredients_block:
            ing = normalize_ingredient_line(raw)
            if ing:
                candidates.append(ing)
    else:
        for raw in lines:
            if not raw:
                continue
            if raw.strip().startswith(("-", "*", "•")) or re.search(r"\d", raw):
                ing = normalize_ingredient_line(raw)
                if ing:
                    candidates.append(ing)

    seen = set()
    deduped: List[str] = []
    for ing in candidates:
        if ing not in seen:
            seen.add(ing)
            deduped.append(ing)
        if len(deduped) >= limit:
            break
    return deduped


def extract_text_from_pdf(file_bytes: bytes) -> str:
    if not HAS_PDF:
        raise RuntimeError("PDF parsing is not available on this server.")
    try:
        reader = PyPDF2.PdfReader(io.BytesIO(file_bytes))
        pages_text = []
        for page in reader.pages:
            try:
                pages_text.append(page.extract_text() or "")
            except Exception:
                continue
        return "\n".join(pages_text).strip()
    except Exception as e:
        raise RuntimeError(f"Failed to read PDF: {e}")

# --------- External Knowledge Lookups ---------

def http_get_json(url: str, params: Optional[dict] = None, timeout: float = HTTP_TIMEOUT) -> Optional[dict]:
    try:
        r = requests.get(url, params=params, headers=USER_AGENT, timeout=timeout)
        if r.status_code == 200:
            return r.json()
        else:
            logger.warning(f"GET {url} returned {r.status_code}")
            return None
    except requests.RequestException as e:
        logger.warning(f"GET {url} failed: {e}")
        return None


def truncate(text: str, max_len: int = 300) -> str:
    if not text:
        return ""
    text = re.sub(r"\s+", " ", text).strip()
    return (text[: max_len - 1] + "…") if len(text) > max_len else text


def wiki_summary(term: str) -> Optional[str]:
    safe_title = term.replace(" ", "_")
    url = f"https://en.wikipedia.org/api/rest_v1/page/summary/{requests.utils.quote(safe_title)}"
    try:
        r = requests.get(url, headers=USER_AGENT, timeout=HTTP_TIMEOUT)
        if r.status_code == 200:
            data = r.json()
            extract = data.get("extract") or ""
            if extract:
                return truncate(extract, 420)
    except requests.RequestException:
        pass

    search_api = "https://en.wikipedia.org/w/api.php"
    sdata = http_get_json(search_api, {
        "action": "opensearch",
        "search": term,
        "limit": 1,
        "namespace": 0,
        "format": "json",
        "redirects": "resolve",
    })
    if sdata and len(sdata) >= 4 and sdata[1]:
        title = sdata[1][0]
        edata = http_get_json(search_api, {
            "action": "query",
            "prop": "extracts",
            "exintro": 1,
            "explaintext": 1,
            "redirects": 1,
            "titles": title,
            "format": "json",
        })
        if edata:
            pages = edata.get("query", {}).get("pages", {})
            for _, p in pages.items():
                ext = p.get("extract")
                if ext:
                    return truncate(ext, 420)
    return None


def wikidata_description(term: str) -> Optional[str]:
    url = "https://www.wikidata.org/w/api.php"
    data = http_get_json(url, {
        "action": "wbsearchentities",
        "language": "en",
        "format": "json",
        "search": term,
        "limit": 1,
    })
    if data and data.get("search"):
        desc = data["search"][0].get("description")
        return truncate(desc, 160) if desc else None
    return None


def datamuse_adjectives(noun: str, maxn: int = 5) -> List[str]:
    url = "https://api.datamuse.com/words"
    try:
        r = requests.get(url, params={"rel_jjb": noun, "max": maxn}, headers=USER_AGENT, timeout=HTTP_TIMEOUT)
        if r.status_code == 200:
            words = [w.get("word") for w in r.json() if w.get("word")]
            keep = []
            seen = set()
            for w in words:
                lw = w.lower()
                if lw in seen:
                    continue
                if lw in {"good", "many", "more", "much", "little", "other"}:
                    continue
                seen.add(lw)
                keep.append(lw)
            return keep[:maxn]
    except requests.RequestException:
        pass
    return []


def datamuse_similar(noun: str, maxn: int = 5) -> List[str]:
    url = "https://api.datamuse.com/words"
    try:
        r = requests.get(url, params={"ml": noun, "max": maxn}, headers=USER_AGENT, timeout=HTTP_TIMEOUT)
        if r.status_code == 200:
            words = [w.get("word") for w in r.json() if w.get("word")]
            keep = []
            seen = set()
            for w in words:
                lw = w.lower()
                if lw in seen or " " in lw:
                    continue
                seen.add(lw)
                keep.append(lw)
            return keep[:maxn]
    except requests.RequestException:
        pass
    return []


LOOKUP_CACHE: Dict[str, Dict] = {}


def fetch_knowledge_for_ingredient(ing: str) -> Dict:
    if ing in LOOKUP_CACHE:
        return LOOKUP_CACHE[ing]

    summary = wiki_summary(ing) or ""
    desc = wikidata_description(ing) or ""
    adjs = datamuse_adjectives(ing, maxn=5)
    related = datamuse_similar(ing, maxn=5)

    data = {
        "ingredient": ing,
        "wikipedia_summary": summary,
        "wikidata_description": desc,
        "adjectives": adjs,
        "related": related,
        "sources": {
            "wikipedia": f"https://en.wikipedia.org/wiki/{requests.utils.quote(ing.replace(' ', '_'))}",
            "wikidata_search": f"https://www.wikidata.org/w/index.php?search={requests.utils.quote(ing)}",
            "datamuse": "https://api.datamuse.com/words"
        }
    }
    LOOKUP_CACHE[ing] = data
    return data

# --------- Spell Generator ---------

FALLBACK_ADJS = ["mystic", "luminous", "ancient", "whispering", "emberlit"]
FALLBACK_VERBS = ["stir", "summon", "invoke", "weave", "conjure"]
FALLBACK_ENDINGS = ["So mote it be.", "Thus the charm is sealed.", "Let the spell be done."]


def build_spell(ingredients: List[str], lore: Dict[str, Dict]) -> str:
    if not ingredients:
        return "Whisper into the empty cauldron; no ingredients, no incantation."

    adj_pool = []
    for ing in ingredients:
        adj_pool.extend(lore.get(ing, {}).get("adjectives") or [])
    if not adj_pool:
        adj_pool = FALLBACK_ADJS[:]

    random.shuffle(adj_pool)
    epithets = ", ".join(adj_pool[:3]) if adj_pool else "mystic"

    lines = []
    lines.append(f"Hear me, {epithets} winds, as I bind this recipe's essence:")

    for ing in ingredients:
        d = lore.get(ing, {})
        bits = []
        if d.get("wikidata_description"):
            bits.append(d["wikidata_description"])  # short descriptor
        elif d.get("wikipedia_summary"):
            bits.append(truncate(d["wikipedia_summary"], 120))
        rel = d.get("related") or []
        if rel:
            bits.append(f"akin to {random.choice(rel)}")
        verb = random.choice(FALLBACK_VERBS)
        line = f"- {verb.title()} the {ing} — {'; '.join(bits) if bits else 'let its spirit awaken.'}"
        lines.append(line)

    lines.append("")
    lines.append("With breath and beat, intentions rise; circle closed and will made free.")
    lines.append(random.choice(FALLBACK_ENDINGS))

    return "\n".join(lines)

# --------- HTML Rendering Helpers ---------

CSS_BASE = """
body{font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;margin:0;background:#0b0c10;color:#e6f1ff}
.container{max-width:760px;margin:0 auto;padding:24px}
.card{background:#11131a;border:1px solid #1f2330;border-radius:12px;padding:20px;box-shadow:0 6px 24px rgba(0,0,0,.35)}
.h1{font-size:22px;margin:0 0 12px}
.small{color:#9fb0c3;font-size:13px}
input[type=file],textarea,button{width:100%}
