button{margin-top:12px;padding:12px 14px;border-radius:8px;border:0;background:#3b82f6;color:#fff;font-weight:600;cursor:pointer}
button:disabled{opacity:.6;cursor:not-allowed}
.error{background:#2a0f14;border:1px solid #5a1b23;color:#ffd7d7;padding:12px;border-radius:8px;margin:12px 0}
