.footer{margin-top:14px;color:#93a4b8;font-size:12px}
hr{border:0;border-top:1px solid #1f2330;margin:16px 0}
.source{font-size:12px;color:#9fb0c3}
pre{white-space:pre-wrap}
"""


def page(title: str, body_html: str, status: int = 200) -> tuple:
    html_doc = f"""
<!doctype html>
<html lang=\"en\">
<head>
  <meta charset=\"utf-8\">
  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">
  <title>{html.escape(title)}</title>
  <style>{CSS_BASE}</style>
</head>
<body>
  <div class=\"container\">{body_html}</div>
</body>
</html>
"""
    resp = make_response(html_doc, status)
    resp.headers["Content-Security-Policy"] = "default-src 'none'; img-src https: data:; style-src 'unsafe-inline'; form-action 'self'; frame-ancestors *; base-uri 'none'"
    resp.headers["X-Content-Type-Options"] = "nosniff"
    resp.headers["Referrer-Policy"] = "no-referrer"
    return resp

# --------- /embed UI + Handlers ---------

ALLOWED_EXTS = {"txt", "pdf"}
MAX_TEXT_LEN = 40_000  # chars after extraction/reading


@app.get("/embed")
def embed_form():
    body = f"""
    <div class=\"card\">
      <h1 class=\"h1\">Spell from Recipe</h1>
      <p class=\"small\">Paste your recipe text or upload a .txt/.pdf file. We'll extract ingredients, gather public lore, and weave a whimsical spell.</p>
      <form action=\"/embed\" method=\"post\" enctype=\"multipart/form-data\">
        <label class=\"small\" for=\"recipe_text\">Paste recipe</label>
        <textarea id=\"recipe_text\" name=\"recipe_text\" placeholder=\"Ingredients...\"></textarea>
        <hr/>
        <label class=\"small\" for=\"recipe_file\">Or upload .txt or .pdf (max 2 MB)</label>
        <input id=\"recipe_file\" name=\"recipe_file\" type=\"file\" accept=\".txt,application/pdf\">
        <button type=\"submit\">Conjure Spell</button>
      </form>
      <div class=\"footer\">By submitting, you agree not to upload sensitive or copyrighted material.</div>
    </div>
    """
    return page("Spell from Recipe", body)


def error_box(msg: str) -> str:
    return f"<div class=\\"error\\">{html.escape(msg)}</div>"


def success_box(msg: str) -> str:
    return f"<div class=\\"success\\">{html.escape(msg)}</div>"


def read_text_from_request() -> str:
    # Strict precedence: uploaded file if present, else pasted text
    uploaded = request.files.get("recipe_file")
    pasted = request.form.get("recipe_text", "")

    if uploaded and uploaded.filename:
        filename = uploaded.filename
        ext = filename.rsplit(".", 1)[-1].lower() if "." in filename else ""
        if ext not in ALLOWED_EXTS:
            raise ValueError("Unsupported file type. Please upload .txt or .pdf only.")
        # Read bytes within Flask MAX_CONTENT_LENGTH (2 MB). Additional guard:
        file_bytes = uploaded.read()
        if len(file_bytes) > app.config["MAX_CONTENT_LENGTH"]:
            raise ValueError("File is too large. Maximum size is 2 MB.")
        if ext == "txt":
            try:
                text = file_bytes.decode("utf-8", errors="ignore")
            except Exception:
                text = file_bytes.decode("latin-1", errors="ignore")
        else:  # pdf
            text = extract_text_from_pdf(file_bytes)
        return text

    # No file: fall back to pasted text
    text = (pasted or "").strip()
    if not text:
        raise ValueError("Please paste a recipe or upload a .txt/.pdf file.")
    return text


@app.post("/embed")
def embed_submit():
    try:
        text = read_text_from_request()
        if len(text) > MAX_TEXT_LEN:
            raise ValueError("Text is too long. Please provide a shorter recipe (under 40k characters).")

        ings = extract_ingredients_from_text(text)
        if not ings:
            body = f"""
            <div class=\"card\">{error_box('No ingredients found. Please ensure your recipe includes an Ingredients section or quantity lines.')}
              <a href=\"/embed\"><button>Try Again</button></a>
            </div>
            """
            return page("No ingredients found", body, 400)

        lore: Dict[str, Dict] = {}
        for ing in ings:
            try:
                lore[ing] = fetch_knowledge_for_ingredient(ing)
            except Exception as e:
                logger.warning(f"Lookup failed for {ing}: {e}")
                lore[ing] = {"ingredient": ing, "adjectives": [], "related": []}

        spell = build_spell(ings, lore)

        # Render result page
        items_html = "".join(
            f"<li><strong>{html.escape(ing)}</strong> — "
            f"<span class=\\"source\\">"
            f"<a href=\\"{html.escape(d.get('sources', {}).get('wikipedia',''))}\\" target=\\"_blank\\">Wikipedia</a> • "
            f"<a href=\\"{html.escape(d.get('sources', {}).get('wikidata_search',''))}\\" target=\\"_blank\\">Wikidata</a>"
            f"</span></li>" for ing, d in lore.items()
        )

        body = f"""
        <div class=\"card\">
          {success_box('Spell conjured from your recipe!')}
          <h1 class=\"h1\">Your Spell</h1>
          <pre>{html.escape(spell)}</pre>
          <hr/>
          <h2 class=\"h1\">Ingredients & Sources</h2>
          <ul>{items_html}</ul>
          <a href=\"/embed\"><button>Conjure Another</button></a>
        </div>
        """
        return page("Spell Result", body)

    except ValueError as ve:
        body = f"""
        <div class=\"card\">{error_box(str(ve))}
          <a href=\"/embed\"><button>Back</button></a>
        </div>
        """
        return page("Submission error", body, 400)
    except Exception as e:
        logger.exception("Unexpected error")
        body = f"""
        <div class=\"card\">{error_box('An unexpected error occurred while processing your submission. Please try again.')}
          <div class=\"small\">{html.escape(str(e))}</div>
          <a href=\"/embed\"><button>Back</button></a>
        </div>
        """
