plPrice = ta.pivotlow(low,  leftLen, rightLen)

isPH = not na(phPrice)
isPL = not na(plPrice)

// Bar index where the pivot actually forms (confirmed)
phBarIndex = isPH ? bar_index - rightLen : na
plBarIndex = isPL ? bar_index - rightLen : na

