if showPivotHighs and isPH
    label.new(phBarIndex, phPrice, text="PH", style=label.style_label_down, color=color.new(phColor, 0), textcolor=color.white, size=f_size(phSize))

if showPivotLows and isPL
    label.new(plBarIndex, plPrice, text="PL", style=label.style_label_up, color=color.new(plColor, 0), textcolor=color.white, size=f_size(plSize))

// Optional lines to extend from the pivot point (for visibility)
extendLines = input.bool(true, "Draw small lines at pivots")
lineLenBars = input.int(10, "Pivot line length (bars)", minval=1, maxval=200)

var line phLines = na
var line plLines = na
if extendLines and isPH
    phLines := line.new(phBarIndex, phPrice, phBarIndex + lineLenBars, phPrice, xloc=xloc.bar_index, extend=extend.none, color=color.new(phColor, 0), style=line.style_solid, width=2)
if extendLines and isPL
    plLines := line.new(plBarIndex, plPrice, plBarIndex + lineLenBars, plPrice, xloc=xloc.bar_index, extend=extend.none, color=color.new(plColor, 0), style=line.style_solid, width=2)

//========================
// Missed Pivot Tracking
// A missed pivot is defined here as a confirmed pivot whose price level
// has not been revisited/"touched" by price after its confirmation.
// For pivot highs: consider missed until close/High trades >= pivot price.
// For pivot lows:  consider missed until close/Low trades <= pivot price.
//========================

type PivotRec
    int   bIndex
    float price

var PivotRec[] openHighPivots = array.new<PivotRec>()
var PivotRec[] openLowPivots  = array.new<PivotRec>()

// Add newly confirmed pivots to tracking arrays
if isPH
    array.push(openHighPivots, PivotRec.new(phBarIndex, phPrice))
if isPL
    array.push(openLowPivots, PivotRec.new(plBarIndex, plPrice))

// Function to prune old entries
f_prune(arr, maxAge) =>
    i = 0
    while i < array.size(arr)
        rec = array.get(arr, i)
        tooOld = (bar_index - rec.bIndex) > maxAge
        if tooOld
            array.remove(arr, i)
        else
            i += 1

// Update/prune arrays each bar
f_prune(openHighPivots, missedLookbackBars)
f_prune(openLowPivots,  missedLookbackBars)

// Check for tests that resolve missed status
f_check_resolved_highs() =>
    // If price trades back to or above the pivot-high price, it's no longer missed
    i = 0
    while i < array.size(openHighPivots)
        rec = array.get(openHighPivots, i)
        tested = high >= rec.price
        if tested
            array.remove(openHighPivots, i)
        else
            i += 1

f_check_resolved_lows() =>
    // If price trades back to or below the pivot-low price, it's no longer missed
    i = 0
    while i < array.size(openLowPivots)
        rec = array.get(openLowPivots, i)
        tested = low <= rec.price
        if tested
            array.remove(openLowPivots, i)
        else
            i += 1

f_check_resolved_highs()
f_check_resolved_lows()

//========================
// Missed Pivot Alerts
