//========================
newMissedPH = isPH and (high < phPrice)   // on the confirmation bar, price hasn't revisited >= pivot
newMissedPL = isPL and (low  > plPrice)   // on the confirmation bar, price hasn't revisited <= pivot

missedPHCond = alertMissedHighs and newMissedPH
missedPLCond = alertMissedLows  and newMissedPL

