phMsg = "Missed Pivot High at " + str.tostring(phPrice, format.mintick) + " (bar " + str.tostring(phBarIndex) + ")"
plMsg = "Missed Pivot Low at "  + str.tostring(plPrice, format.mintick) + " (bar " + str.tostring(plBarIndex) + ")"

alertcondition(missedPHCond, title="Missed Pivot High", message=phMsg)
alertcondition(missedPLCond, title="Missed Pivot Low",  message=plMsg)

// Optional on-chart warning markers for missed pivots at confirmation bar
showMissedMarkers = input.bool(true, "Plot markers on missed pivots")
if showMissedMarkers and newMissedPH
    label.new(phBarIndex, phPrice, text="Missed PH", style=label.style_label_down, color=color.new(color.orange, 0), textcolor=color.white, size=size.large)
