        sceneCanvas.width = desiredW;
        sceneCanvas.height = desiredH;
        labelCanvas.width = desiredW;
        labelCanvas.height = desiredH;
        sceneCtx.setTransform(dpr, 0, 0, dpr, 0, 0); // scale drawing ops to CSS pixels
        labelCtx.setTransform(dpr, 0, 0, dpr, 0, 0);
