    // render/labelManager.js
    import RBush from 'rbush';
    import { worldToScreen, getView } from './scale.js';

    const index = new RBush();

    // Call each frame or when positions change significantly
    export function buildLabelIndex(bodies, ctx) {
      index.clear();
      const view = getView();
      const items = [];
      for (const b of bodies) {
        const p = worldToScreen(b.pos, view);
        if (!p) continue;
        const text = b.name;
        ctx.font = '12px system-ui';
        const w = Math.ceil(ctx.measureText(text).width) + 6;
        const h = 14;
        const x = p.x + 8; // offset label to the right of the body
        const y = p.y - h / 2;
        const item = { minX: x, minY: y, maxX: x + w, maxY: y + h, id: b.id, text, px: p.x, py: p.y };
        // Check collisions
        if (index.search(item).length === 0) {
          index.insert(item);
          items.push(item);
        }
      }
      return items; // visible labels to draw this frame
    }

    // Simple screen-space hit test for selecting the nearest body
    export function hitTest(screenX, screenY, bodies, view, maxPx = 8) {
      let best = null;
      let bestD2 = maxPx * maxPx;
      for (const b of bodies) {
        const p = worldToScreen(b.pos, view);
        if (!p) continue;
        const dx = p.x - screenX;
        const dy = p.y - screenY;
        const d2 = dx*dx + dy*dy;
        if (d2 < bestD2) {
          bestD2 = d2;
          best = b;
        }
      }
      return best; // null if none within radius
    }

    export function drawLabels(ctx, items) {
      ctx.save();
      ctx.font = '12px system-ui';
      ctx.textBaseline = 'middle';
      for (const it of items) {
        // halo
        ctx.fillStyle = 'rgba(0,0,0,0.6)';
        ctx.fillRect(it.minX, it.minY, it.maxX - it.minX, it.maxY - it.minY);
        // text
        ctx.fillStyle = '#ddd';
        ctx.fillText(it.text, it.minX + 3, it.minY + (it.maxY - it.minY)/2);
      }
      ctx.restore();
    }
