    // render/scale.js
    export function getView() {
      return {
        center: { x: 0, y: 0 }, // world units (AU)
        zoom: 200,              // pixels per AU (example value)
        width: document.getElementById('sceneCanvas').clientWidth,
        height: document.getElementById('sceneCanvas').clientHeight,
      };
    }

    export function worldToScreen(pos, view) {
      // Culling: if far outside view, return null
      const x = view.width/2 + (pos[0] - view.center.x) * view.zoom;
      const y = view.height/2 + (pos[1] - view.center.y) * view.zoom;
      if (x < -50 || y < -50 || x > view.width + 50 || y > view.height + 50) return null;
      return { x, y };
    }
